for p in [S/'fonts/NotoSansSC-Regular.ttf',C/'uploads/NotoSansSC-Regular.ttf',C/'ds/still/fonts/NotoSansSC-Regular.ttf']:
 if p.resolve()!=font_source.resolve():shutil.copy2(font_source,p)
license_source=next((p for p in [BOOK/'assets/fonts/OFL.txt',S/'fonts/OFL.txt'] if p.exists()),None)
if license_source:
 for p in [S/'fonts/OFL.txt',C/'uploads/OFL.txt',C/'ds/still/fonts/OFL.txt']:
  if p.resolve()!=license_source.resolve():shutil.copy2(license_source,p)
