if photo.exists():
 for p in [S/'assets/Photography/still-coffee.png',C/'uploads/still-coffee.png']:shutil.copy2(photo,p)
else:print('AI photo pending: shared-assets/still-coffee.png; rerun this builder when it is ready')
def write(p,t):p.write_text(t)
