now=datetime.datetime.now(datetime.timezone.utc).isoformat()
colors=[('surface',{'light':'#E9DFCF','night':'#173F37'},'画布底色。'),('surface-raised',{'light':'#F5F0E7','night':'#214F45'},'纸面、卡片与对话层。'),('ink',{'light':'#332C25','night':'#F5F0E7'},'正文：在surface和surface-raised上。'),('ink-muted',{'light':'#655A4E','night':'#D8CEBC'},'辅助文字：在surface和surface-raised上。'),('accent',{'light':'#173F37','night':'#E9DFCF'},'主要行动填充、选中态。'),('on-accent',{'light':'#F5F0E7','night':'#173F37'},'仅在accent上。'),('terracotta',{'light':'#A74E32','night':'#E6AA8E'},'大号风味编号及装饰；小字使用clay-text。'),('clay-text',{'light':'#954128','night':'#E6AA8E'},'小号风味提示：在surface和surface-raised上。'),('line',{'light':'#A79C89','night':'#6E887D'},'结构线；不单独传达选中状态。'),('photo-bed',{'light':'#D8CEBC','night':'#102E27'},'摄影留边，不承载正文。')]
tokens={'name':'隙间 / STILL','version':1,'color':{'themes':[{'id':'light','name':'暖石 / 日间'},{'id':'night','name':'深绿 / 夜间'}],'tokens':[{'name':n,'value':v,'usage':u} for n,v,u in colors]},'type':{'fonts':[{'family':'STILL Sans','file':'fonts/NotoSansSC-Regular.ttf','weight':'400'}],'families':{'sans':'"STILL Sans", "Noto Sans SC", sans-serif','editorial':'Georgia, "Times New Roman", serif'},'groups':[{'name':'中文阅读','family':'sans','styles':[{'name':n,'fontSize':f'{size}px','lineHeight':lh,'fontWeight':400,'usage':u} for n,size,lh,u in [('display',76,1.18,'单句品牌主张。'),('title',44,1.28,'版块与包装主标题。'),('subtitle',24,1.45,'商品名称与导语。'),('body',18,1.7,'说明与购买信息。'),('caption',14,1.55,'非关键注记，不承担价格与主要行动。')]]},{'name':'英文品牌','family':'editorial','styles':[{'name':'wordmark','fontSize':'72px','lineHeight':1,'fontWeight':400,'letterSpacing':'4px','usage':'STILL字标，保留大尺度留白。'}]}]},'spacing':{'tokens':[{'name':f'space-{n}','value':f'{n}px','usage':u} for n,u in [(4,'字与辅助符号'),(8,'标签组'),(16,'组件内部'),(24,'信息组'),(40,'卡片'),(64,'大版块'),(96,'宽画板边距')]]},'radius':{'tokens':[{'name':'radius-none','value':'0px','usage':'包装与信息面。'},{'name':'radius-small','value':'2px','usage':'按钮细微触感。'},{'name':'radius-pill','value':'40px','usage':'仅风味标签。'}]},'shadow':{'tokens':[{'name':'shadow-soft','value':'0 8px 30px rgba(51,44,37,0.06)','usage':'浮层；纸面布局不使用假立体。'}]}}
jsave(S/'tokens.json',tokens);jsave(C/'ds/still/tokens.json',tokens)
if not (S/'design-system.json').exists() or not (C/'canvas.json').exists():raise FileNotFoundError('Run native tingly-design new design-system/canvas for these two folders first')
idx=json.loads((S/'design-system.json').read_text());idx.update({'title':'隙间 / STILL','namespace':'STILL','groups':[{'name':'产品与行动'}],'assetGroups':{'Photography':{'title':'材料与场景摄影'}},'lastChange':{'by':'Codex','at':now,'via':'native-files','note':'恢复原创系统：双主题、三组件、五画板'}});jsave(S/'design-system.json',idx)
write(S/'components/bundle.css','''*{box-sizing:border-box}.still-button{font:400 18px/1.4 var(--font-sans,"STILL Sans",sans-serif);padding:16px 28px;min-height:56px;border:1px solid var(--accent);border-radius:var(--radius-small);background:var(--accent);color:var(--on-accent);cursor:pointer}.still-button[data-variant="outline"]{background:transparent;color:var(--ink);border-color:var(--ink)}.still-button:focus-visible{outline:3px solid var(--clay-text);outline-offset:4px}.still-button:disabled{opacity:.55;cursor:not-allowed}.still-flavor{display:inline-flex;align-items:center;gap:8px;font:400 14px/1.4 "STILL Sans",sans-serif;padding:7px 14px;border:1px solid var(--line);border-radius:var(--radius-pill);color:var(--ink);background:var(--surface-raised)}.still-product{font:400 16px/1.6 "STILL Sans",sans-serif;background:var(--surface-raised);color:var(--ink);padding:24px;width:340px;display:flex;flex-direction:column;gap:16px;border:1px solid var(--line)}.still-product img{width:100%;height:170px;object-fit:cover}.still-product h3{font-size:24px;line-height:1.4;font-weight:400;margin:0}.still-product p{margin:0;color:var(--ink-muted)}.still-product footer{display:flex;align-items:center;justify-content:space-between;gap:16px}.still-product .still-button{font-size:14px;padding:10px 16px;min-height:42px}.still-preview{display:flex;flex-wrap:wrap;align-items:flex-start;gap:var(--space-24);padding:var(--space-24);background:var(--surface);color:var(--ink)}''')
write(S/'components/bundle.js','''/* @ds-bundle: {"format":4,"namespace":"STILL","components":[{"name":"ActionButton"},{"name":"FlavorTag"},{"name":"ProductCard"}]} */
(function(){function el(tag,cls,text){var n=document.createElement(tag);if(cls)n.className=cls;if(text!=null)n.textContent=text;return n;}
function ActionButton(p){p=p||{};var n=el('button','still-button',p.label||'加入订阅');n.type='button';n.dataset.variant=p.variant||'solid';n.disabled=!!p.disabled;if(p.onClick)n.addEventListener('click',p.onClick);return n;}
function FlavorTag(p){p=p||{};return el('span','still-flavor',p.label||'坚果 · 可可');}
function ProductCard(p){p=p||{};var n=el('article','still-product'),im=el('img');im.src=p.image||'../../assets/Photography/still-coffee.png';im.alt='AI生成材料情境摄影：绿釉咖啡杯与牛皮纸袋';n.appendChild(im);n.appendChild(el('p','',p.series||'01 / 日常拼配'));n.appendChild(el('h3','',p.name||'把早晨留给自己'));n.appendChild(FlavorTag({label:p.flavor||'榛果 · 可可 · 焦糖'}));n.appendChild(el('p','',p.description||'中度烘焙，250 g。适合手冲与奶咖。'));var f=el('footer');f.appendChild(el('strong','',p.price||'¥ 68'));f.appendChild(ActionButton({label:p.action||'查看咖啡',onClick:p.onClick}));n.appendChild(f);return n;}
window.STILL={ActionButton:ActionButton,FlavorTag:FlavorTag,ProductCard:ProductCard};})();''')
write(S/'components/index.d.ts','''interface ActionButtonProps {label:string;variant?:"solid"|"outline";disabled?:boolean;onClick?:()=>void}
interface FlavorTagProps {label:string}
interface ProductCardProps {name:string;series?:string;flavor?:string;description?:string;price?:string;image?:string;action?:string;onClick?:()=>void}
declare const STILL:{ActionButton(p:ActionButtonProps):HTMLButtonElement;FlavorTag(p:FlavorTagProps):HTMLSpanElement;ProductCard(p:ProductCardProps):HTMLElement};''')
