for name,(sub,h,body) in previews.items():
 p=S/'components'/name;p.mkdir(exist_ok=True);write(p/'preview.html',f'''<!-- @dsCard group="产品与行动" height={h} subtitle="{sub}" -->
<!doctype html><html lang="zh"><head><meta charset="utf-8"></head><body><div id="root" class="still-preview"></div><script>var root=document.getElementById('root');{body}</script></body></html>''')
for name,text in {'ActionButton':'主要行动用深绿实心按钮，次行动用描边，文字说明下一步。\n\n支持label、variant、disabled、onClick；焦点有独立轮廓，禁用仍需邻近解释。','FlavorTag':'风味标签使用可读词语，不以颜色独自编码。\n\n标签不是按钮；筛选应另用有选择语义的控件。','ProductCard':'商品卡保留系列、名称、风味、规格、价格与下一步，允许名称自然换行。\n\nAI情境图不是具体产地或商品证据。onClick承接实际产品路由。'}.items():write(S/'components'/name/'README.md',text)
p=S/'components/Cover';p.mkdir(exist_ok=True);write(p/'preview.html','''<!-- @dsCard group="品牌概览" height=380 subtitle="把一杯咖啡，留在日常的隙间。" -->
<!doctype html><html lang="zh"><head><meta charset="utf-8"></head><body><section style="padding:48px;background:var(--surface);color:var(--ink);font-family:'STILL Sans',sans-serif"><div style="font:72px/1 Georgia,serif;letter-spacing:6px">STILL</div><p style="font-size:28px;margin:24px 0">隙间 · 把时间，留一点给自己。</p><p style="font-size:18px;line-height:1.8;max-width:780px">不是更快喝完的一杯，而是愿意停下来的一刻。以暖石、深绿与陶土，让材料、信息与呼吸各有位置。</p></section></body></html>''')
