props={'productname':{'default':'晨间 / 日常拼配'},'series':{'default':'01 / EVERYDAY'},'flavor':{'default':'榛果 · 可可 · 焦糖'},'price':{'default':'¥ 68'},'ink':{'editor':'color','default':'#332C25'},'paper':{'editor':'color','default':'#F5F0E7'}}
card='''<article style="padding:24px;width:100%;height:100%;box-sizing:border-box;background:{{paper}};color:{{ink}};border:1px solid #A79C89;display:flex;flex-direction:column;gap:14px"><div style="font-size:14px;letter-spacing:2px">{{series}}</div><h3 style="font-size:26px;line-height:1.4;font-weight:400;margin:0;overflow-wrap:anywhere">{{productname}}</h3><span style="align-self:start;padding:7px 14px;border:1px solid #A79C89;border-radius:40px;font-size:14px">{{flavor}}</span><p style="font-size:15px;line-height:1.7;margin:0">250 g 咖啡豆 · 中度烘焙<br>从一杯日常，找到自己的节奏。</p><footer style="margin-top:auto;display:flex;justify-content:space-between;align-items:center"><span style="font-size:23px;white-space:nowrap;flex-shrink:0">{{price}}</span><span style="font-size:15px;text-decoration:underline;white-space:nowrap">认识这支咖啡 →</span></footer></article>'''
board('ProductCard.dc.html','商品卡 / 可调用Canvas模板',405,275,card,logic='return {productname:this.props.productname,series:this.props.series,flavor:this.props.flavor,price:this.props.price,ink:this.props.ink,paper:this.props.paper};',props=props,pad=0,bg='#F5F0E7')
cards=''.join(f'<dc-import name="ProductCard" productname="{name}" series="{num} / {en}" flavor="{flavor}" price="¥ {price}" hint-size="405px,275px"></dc-import>' for num,en,name,flavor,col,desc,price in products)
inner=f'''<header style="display:flex;justify-content:space-between;align-items:center">{BRAND}<nav style="display:flex;gap:36px;font-size:17px"><a href="#coffee" style="text-decoration:none">咖啡</a><a href="#subscription" style="text-decoration:none">隙间订阅</a><span>关于隙间</span><span>购物袋（0）</span></nav></header>{line()}<section style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:54px"><div style="display:flex;flex-direction:column;justify-content:center;gap:20px"><div style="font-size:14px;letter-spacing:3px;color:#954128">每月两袋，按你的节奏。</div><h1 style="font-size:58px;line-height:1.22;font-weight:400;margin:0">咖啡如期而至，<br>日子不必赶。</h1><p style="font-size:18px;line-height:1.8;margin:0;max-width:550px">选一支熟悉的日常，再留一支给新鲜。<br>下一次发货前可调整、跳过或暂停。</p><div style="display:flex;gap:12px">{btn('每月订阅',True,'onClick="{{pickMonthly}}"')}{btn('先试一次',False,'onClick="{{pickOnce}}"')}</div><p role="status" style="font-size:16px;color:#655A4E;margin:0">{hole('planText')}</p></div><img src="uploads/still-coffee.png" alt="AI咖啡材料情境摄影" style="width:100%;height:410px;object-fit:cover;object-position:48% 50%"></section><section id="coffee" style="display:flex;flex-direction:column;gap:20px"><div style="display:flex;justify-content:space-between;align-items:baseline"><h2 style="font-size:30px;font-weight:400;margin:0">这一期，留给你的三种隙间。</h2><span style="font-size:15px;color:#655A4E;white-space:nowrap">价格为虚构教学示例 / 250 g</span></div><div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px">{cards}</div></section><footer id="subscription" style="display:flex;justify-content:space-between;align-items:center;padding:24px 0;border-top:1px solid #A79C89"><div><div style="font-size:23px">{hole('summary')}</div><div style="font-size:15px;color:#655A4E;margin-top:8px">由日常拼配与当季单品组成；发货前仍可调整。</div></div><div style="display:flex;gap:20px;align-items:center">{btn('{{actionText}}',True,'onClick="{{addPlan}}"')}<span role="status" style="font-size:16px;max-width:240px">{hole('feedback')}</span></div></footer>'''
logic="const monthly=this.state.monthly;return {planText:monthly?'每月两袋 / ¥ 148 · 发货前可暂停':'一次体验 / ¥ 156 · 不自动续订',summary:monthly?'每月订阅 · 两袋 500 g / ¥ 148':'一次体验 · 两袋 500 g / ¥ 156',actionText:this.state.added?'已加入体验清单':'选择这份隙间',feedback:this.state.added?'已记录当前选择。此教学原型不下单、不扣款。':'',pickMonthly:()=>this.setState({monthly:true,added:false}),pickOnce:()=>this.setState({monthly:false,added:false}),addPlan:()=>this.setState({added:true})};"
board('Subscription.dc.html','04 订阅电商 · 可选择计划',1440,1100,inner,logic=logic)
inner=f'''<header style="display:flex;justify-content:space-between;align-items:center;color:#F5F0E7">{BRAND}<div style="font-size:14px;letter-spacing:2px">压力测试 / NIGHT THEME + LONG COPY</div></header><div style="height:1px;background:#6E887D"></div><section style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:64px;flex:1"><div style="display:flex;flex-direction:column;gap:24px;color:#F5F0E7"><div style="font-size:15px;color:#E6AA8E;letter-spacing:2px">02 / SEASONAL NOTES</div><h1 style="font-size:54px;font-weight:400;line-height:1.28;margin:0">山坡上，<br>花开之后的第一支咖啡。</h1><p style="font-size:21px;line-height:1.8;margin:0">一个比“山坡花开”长得多的名字。标题区域允许自然增高，价格、规格与行动仍然完整。</p><p style="font-size:17px;line-height:1.9;color:#D8CEBC;margin:0">夜间模式没有反相照片。页面表面变深，正文与主要行动成对换色；陶土提示改为更明亮的杏陶色。<br><br>这组关系保持了内容的优先级，而不是强迫所有元素继续使用同一色值。</p><div style="display:flex;gap:12px;flex-wrap:wrap"><span style="padding:10px 16px;border:1px solid #6E887D;border-radius:40px;font-size:16px">白花 · 柑橘 · 蜂蜜</span><span style="padding:10px 16px;border:1px solid #6E887D;border-radius:40px;font-size:16px">Whole beans / 250 g</span></div><div style="display:flex;align-items:center;gap:28px;margin-top:8px"><span style="font-size:34px">¥ 88</span><button type="button" style="padding:16px 28px;border:1px solid #E9DFCF;background:#E9DFCF;color:#173F37;font-size:18px;border-radius:2px">看看这支当季咖啡</button></div></div><div style="display:flex;flex-direction:column;gap:26px"><img src="uploads/still-coffee.png" alt="原色AI摄影在夜间页面保持原色" style="width:100%;height:440px;object-fit:cover"><div style="padding:28px;border:1px solid #6E887D;display:flex;flex-direction:column;gap:14px;color:#F5F0E7"><div style="font-size:23px">一次有理由的修订</div><p style="font-size:17px;line-height:1.8;margin:0;color:#D8CEBC">原假设：标题永远一行，卡片固定高度。<br>发现：长商品名会被裁切，选择信息受挤压。<br>修订：标题自然换行，信息组保持间距；不缩小正文来“塞下”。</p></div><p style="font-size:15px;line-height:1.8;color:#D8CEBC;margin:0">下一步实测：更长语言、键盘顺序、实际移动端重排。此画板检验视觉规则，不冒充完整商店。</p></div></section>'''
